{
  "clean_text": "校对并分段后的正文",
  "diarized_text": "按说话人整理后的正文（无法判断说话人则填空字符串）",
  "highlights": [{"original": "原文片段", "corrected": "修正后"}],
  "suggestions": [{"type": "typo|term|number|speaker|logic", "original": "原文片段", "suggested": "建议改为", "reason": "理由（20字内）"}]
}
